#include <Arduino.h>
// Пины: D2=GPIO4 центр LED1; D3=GPIO5 LED2+LED7; D10=GPIO10 LED3+LED6; RX=GPIO20 LED4+LED5
// Кнопка SW1: D1=GPIO3 к GND (INPUT_PULLUP), пробуждение по LOW.
const int PIN_C  = D2;
const int PIN_TL_BR = D3;
const int PIN_TR_BL = D10;
const int PIN_ML_MR = RX;
const int PIN_BTN = D1;
const uint32_t IDLE_SLEEP_MS = 30000;
int value = 0;
uint32_t lastAction = 0;
void showValue(int v) {
  bool c=false, tl=false, tr=false, ml=false;
  switch (v) {
    case 1: c=true; break;
    case 2: tl=true; break;
    case 3: tl=true; c=true; break;
    case 4: tl=true; tr=true; break;
    case 5: tl=true; tr=true; c=true; break;
    case 6: tl=true; tr=true; ml=true; break;
    default: break;
  }
  digitalWrite(PIN_C, c ? HIGH : LOW);
  digitalWrite(PIN_TL_BR, tl ? HIGH : LOW);
  digitalWrite(PIN_TR_BL, tr ? HIGH : LOW);
  digitalWrite(PIN_ML_MR, ml ? HIGH : LOW);
}
void roll() {
  uint32_t t0 = millis();
  int v = 1;
  int step = 60;
  while (millis() - t0 < 1200) { v = 1 + random(6); showValue(v); delay(step); step += 25; }
  value = 1 + random(6);
  showValue(value);
}
void goSleep() {
  digitalWrite(PIN_C, LOW); digitalWrite(PIN_TL_BR, LOW);
  digitalWrite(PIN_TR_BL, LOW); digitalWrite(PIN_ML_MR, LOW);
  esp_deep_sleep_enable_gpio_wakeup(1ULL << 3, ESP_GPIO_WAKEUP_GPIO_LOW);
  esp_deep_sleep_start();
}
void setup() {
  pinMode(PIN_C, OUTPUT); pinMode(PIN_TL_BR, OUTPUT);
  pinMode(PIN_TR_BL, OUTPUT); pinMode(PIN_ML_MR, OUTPUT);
  digitalWrite(PIN_C, LOW); digitalWrite(PIN_TL_BR, LOW);
  digitalWrite(PIN_TR_BL, LOW); digitalWrite(PIN_ML_MR, LOW);
  pinMode(PIN_BTN, INPUT_PULLUP);
  randomSeed(esp_random() + analogRead(A0));
  value = 0; showValue(0);
  lastAction = millis();
}
void loop() {
  static bool prevHigh = true;
  bool high = digitalRead(PIN_BTN);
  if (prevHigh && !high) {
    delay(30);
    if (!digitalRead(PIN_BTN)) { roll(); lastAction = millis(); while (!digitalRead(PIN_BTN)) delay(10); delay(30); }
  }
  prevHigh = high;
  if (millis() - lastAction > IDLE_SLEEP_MS) goSleep();
  delay(5);
}

